-- Starter data: the 12 recipes from the prototype, their
-- ingredients, and the two pantry lists. Generated by scripts/make-seed.mjs;
-- edit the fixture at lib/domain/fixtures/sample.ts and regenerate rather
-- than editing this file. Safe to re-run: it inserts only what is missing.

-- Ingredients, including which pantry list each one is on.
insert into app_mealprep.ingredients (household_id, name, default_aisle, pantry_status)
select h.id, v.name, v.aisle::app_mealprep.aisle, v.status::app_mealprep.pantry_status
from app_mealprep.households h
cross join (values
  ('Eggs', 'Dairy & eggs', 'none'),
  ('Liquid egg whites', 'Dairy & eggs', 'none'),
  ('Baby spinach', 'Produce', 'none'),
  ('Feta', 'Dairy & eggs', 'none'),
  ('Red onion', 'Produce', 'none'),
  ('Olive oil', 'Pantry', 'staple'),
  ('Salt', 'Pantry', 'staple'),
  ('Black pepper', 'Pantry', 'staple'),
  ('Rolled oats', 'Pantry', 'usual'),
  ('Vanilla protein powder', 'Pantry', 'usual'),
  ('Chia seeds', 'Pantry', 'usual'),
  ('2% milk', 'Dairy & eggs', 'none'),
  ('Nonfat Greek yogurt', 'Dairy & eggs', 'none'),
  ('Blueberries', 'Produce', 'none'),
  ('Honey', 'Pantry', 'staple'),
  ('Turkey breakfast sausage', 'Meat & fish', 'none'),
  ('Low-carb tortillas', 'Bakery', 'none'),
  ('Reduced-fat cheddar', 'Dairy & eggs', 'none'),
  ('Bell peppers', 'Produce', 'none'),
