  ('Garam masala', 'Pantry', 'staple'),
  ('Garlic', 'Produce', 'usual'),
  ('Lemons', 'Produce', 'none'),
  ('Basmati rice', 'Pantry', 'usual'),
  ('Cucumbers', 'Produce', 'none'),
  ('Cilantro', 'Produce', 'none'),
  ('93% lean ground turkey', 'Meat & fish', 'none'),
  ('Black beans', 'Pantry', 'none'),
  ('Romaine', 'Produce', 'none'),
  ('Limes', 'Produce', 'none'),
  ('Cumin', 'Pantry', 'staple'),
  ('Chili powder', 'Pantry', 'staple'),
  ('Chicken breast', 'Meat & fish', 'none'),
  ('Chickpeas', 'Pantry', 'none'),
  ('Cherry tomatoes', 'Produce', 'none'),
  ('Yellow onions', 'Produce', 'none'),
  ('Fajita seasoning', 'Pantry', 'staple'),
