) as v(name, aisle, status)
on conflict (household_id, name) do nothing;

-- Recipes.
insert into app_mealprep.recipes (household_id, type, name, method, rating, source_kind, source_ref)
select h.id, v.type::app_mealprep.meal_type, v.name, v.method::app_mealprep.method, v.rating::app_mealprep.rating, 'seed'::app_mealprep.source_kind, v.source_ref
from app_mealprep.households h
cross join (values
  ('b', 'Egg bite muffins', 'oven', 'keeper', 'example.com/spinach-egg-bites'),
  ('b', 'Protein overnight oats', 'nocook', 'good', 'example.com/overnight-oats'),
  ('b', 'Turkey sausage breakfast burritos', 'stove', 'good', 'example.com/freezer-burritos'),
  ('l', 'Chicken tikka rice bowls', 'oven', 'keeper', 'example.com/chicken-tikka-bowls'),
  ('l', 'Turkey taco bowls', 'stove', 'good', 'example.com/taco-bowls'),
  ('l', 'Greek chicken chickpea salad', 'oven', 'keeper', 'example.com/greek-chickpea-salad'),
  ('d', 'Sheet-pan chicken fajitas', 'oven', 'keeper', 'example.com/sheet-pan-fajitas'),
  ('d', 'Lemon garlic salmon and broccoli', 'oven', 'good', 'example.com/lemon-salmon'),
  ('d', 'Beef and broccoli stir-fry', 'stove', 'work', 'example.com/beef-broccoli'),
  ('s', 'Cottage cheese berry cups', 'nocook', 'keeper', 'Your own recipe'),
  ('s', 'Crispy roasted chickpeas', 'oven', 'good', 'example.com/roasted-chickpeas'),
  ('s', 'Peanut butter protein bites', 'nocook', 'keeper', 'example.com/protein-bites')
) as v(type, name, method, rating, source_ref)
where not exists (
  select 1 from app_mealprep.recipes r where r.household_id = h.id and r.name = v.name
);

-- One version per recipe, numbered as it was in the prototype so the
-- version badges match.
insert into app_mealprep.recipe_versions
  (household_id, recipe_id, version_no, base_servings, cal, protein_g, carbs_g, fat_g, steps, note, changes)
select r.household_id, r.id, v.version_no, v.base_servings, v.cal, v.protein, v.carbs, v.fat,
       v.steps, v.note, v.changes
from app_mealprep.recipes r
join (values
  ('Egg bite muffins', 2, 4, 220, 24, 6, 11, array['Heat the oven to 350°F and oil a 12-cup muffin tin.', 'Sauté the spinach and onion for 3 minutes, then divide into the cups.', 'Whisk the eggs, egg whites, salt and pepper, and pour over.', 'Top with feta and bake 22 to 25 minutes.', 'Cool completely, then pack 3 per container.'], 'Swapped 4 eggs for egg whites and cheddar for feta. Lighter, same protein.', '{}'::text[]),
  ('Protein overnight oats', 2, 4, 370, 31, 44, 8, array['Stir the oats, protein powder and chia together.', 'Whisk in the milk and yogurt until smooth.', 'Divide into jars and top with blueberries and a drizzle of honey.', 'Refrigerate overnight. Keeps 4 days.'], 'Added protein powder and halved the honey.', '{}'::text[]),
  ('Turkey sausage breakfast burritos', 1, 4, 395, 34, 24, 18, array['Brown the sausage with the diced pepper, then set aside.', 'Soft-scramble the eggs in the same pan.', 'Fill the tortillas with egg, sausage, cheddar and salsa, and roll tight.', 'Wrap in foil. Reheat 90 seconds from the fridge or 3 minutes from frozen.'], 'Original recipe.', '{}'::text[]),
  ('Chicken tikka rice bowls', 3, 4, 470, 42, 52, 10, array['Marinate the chicken in yogurt, garam masala, garlic, lemon juice and salt for at least 30 minutes.', 'Roast at 425°F on a sheet pan for 22 to 25 minutes. Rest, then slice.', 'Cook the rice.', 'Toss the cucumber and onion with lemon and cilantro.', 'Pack rice, chicken and salad in separate sections.'], 'Less rice per bowl and double the garlic.', array['Basmati rice 2 cups to 1½ cups', 'Garlic 3 cloves to 6 cloves']),
  ('Turkey taco bowls', 2, 4, 395, 39, 28, 14, array['Brown the turkey with cumin, chili powder and salt.', 'Rinse and warm the beans.', 'Chop the romaine and pack it separately so it stays crisp.', 'Top with turkey, beans, salsa, cheddar and a lime wedge.'], 'Turkey instead of beef. Romaine base, no rice.', '{}'::text[]),
  ('Greek chicken chickpea salad', 2, 4, 450, 40, 36, 16, array['Season the chicken and roast at 425°F for 20 minutes. Rest, then dice.', 'Rinse the chickpeas. Halve the tomatoes and chop the cucumber.', 'Whisk lemon juice and olive oil for the dressing.', 'Pack the salad and chicken together, dressing on the side.'], 'Dressing on the side so it is not soggy by Thursday.', '{}'::text[]),
  ('Sheet-pan chicken fajitas', 2, 4, 390, 41, 30, 12, array['Slice the chicken, peppers and onions into strips.', 'Toss with oil and fajita seasoning and spread over two sheet pans.', 'Roast at 425°F for 20 minutes, stirring once.', 'Squeeze lime over the top. Pack tortillas and yogurt separately.'], 'Greek yogurt instead of sour cream, and two extra peppers.', '{}'::text[]),
  ('Lemon garlic salmon and broccoli', 1, 4, 460, 38, 32, 20, array['Cook the quinoa.', 'Toss the broccoli with oil and salt and roast at 425°F for 10 minutes.', 'Add the salmon with garlic and lemon slices and roast 12 more minutes.', 'Pack with quinoa.'], 'Original recipe.', '{}'::text[]),
  ('Beef and broccoli stir-fry', 1, 4, 460, 36, 48, 14, array['Slice the steak thin against the grain.', 'Sear in batches over high heat and set aside.', 'Stir-fry the broccoli with ginger and garlic, then add soy and honey.', 'Return the beef, toss, and pack over rice.'], 'Original recipe. Beef went tough on reheating, so slice thinner next time.', '{}'::text[]),
  ('Cottage cheese berry cups', 2, 4, 160, 20, 14, 3, array['Divide the cottage cheese into small containers.', 'Top with berries, a little honey and cinnamon.', 'Keep the berries on top so they stay firm. Eat within 4 days.'], 'Raspberries instead of strawberries. They hold up better in the fridge.', '{}'::text[]),
  ('Crispy roasted chickpeas', 1, 4, 180, 8, 24, 6, array['Rinse the chickpeas and dry them very well.', 'Toss with oil, paprika and salt.', 'Roast at 425°F for 30 to 35 minutes, shaking the pan twice.', 'Cool completely before packing or they go soft.'], 'Original recipe.', '{}'::text[]),
  ('Peanut butter protein bites', 2, 4, 190, 12, 18, 8, array['Stir everything together until it holds when pressed.', 'Roll into 12 bites.', 'Chill 30 minutes, then pack 3 per container.'], 'Swapped half the honey for protein powder.', '{}'::text[])
) as v(recipe_name, version_no, base_servings, cal, protein, carbs, fat, steps, note, changes)
  on v.recipe_name = r.name
where not exists (
  select 1 from app_mealprep.recipe_versions rv
  where rv.recipe_id = r.id and rv.version_no = v.version_no
);

-- Point each recipe at its current version.
update app_mealprep.recipes r
set current_version_id = rv.id
from app_mealprep.recipe_versions rv
where rv.recipe_id = r.id
  and r.current_version_id is distinct from rv.id
  and rv.version_no = (
    select max(version_no) from app_mealprep.recipe_versions where recipe_id = r.id
  );

